mapper.select:
SELECT CAST(NULL AS NUMBER) AS id, TO_CHAR(P.BID_DDLN_DT, 'YYYY-MM-DD') AS eventDate, TO_CHAR(P.BID_DDLN_DT, 'HH24:MI') AS timeText, '제출 마감 · ' || P.PBANC_NM AS title, 'SC010' AS kindCd, TM.TEAM_NM AS teamNm, P.PBANC_SN AS pbancSn FROM TB_BID_PBANC P JOIN TB_TEAM TM ON TM.TEAM_SN = P.SPRVSN_TEAM_SN WHERE P.PBANC_STTS_CD NOT IN ('PS010', 'PS090') AND P.BID_DDLN_DT >= TO_DATE(#{from}, 'YYYY-MM-DD') AND P.BID_DDLN_DT < TO_DATE(#{to}, 'YYYY-MM-DD') + 1
AND P.SPRVSN_TEAM_SN = #{teamSn}
UNION ALL SELECT CAST(NULL AS NUMBER), TO_CHAR(P.PRSNTN_DT, 'YYYY-MM-DD'), TO_CHAR(P.PRSNTN_DT, 'HH24:MI'), '발표 · ' || P.PBANC_NM, 'SC040', TM.TEAM_NM, P.PBANC_SN FROM TB_BID_PBANC P JOIN TB_TEAM TM ON TM.TEAM_SN = P.SPRVSN_TEAM_SN WHERE P.PBANC_STTS_CD NOT IN ('PS010', 'PS090') AND P.PRSNTN_DT >= TO_DATE(#{from}, 'YYYY-MM-DD') AND P.PRSNTN_DT < TO_DATE(#{to}, 'YYYY-MM-DD') + 1
AND P.SPRVSN_TEAM_SN = #{teamSn}
UNION ALL SELECT CAST(NULL AS NUMBER), TO_CHAR(D.SBMSN_DDLN_DT, 'YYYY-MM-DD'), TO_CHAR(D.SBMSN_DDLN_DT, 'HH24:MI'), '서류 마감 · ' || D.DCMNT_NM, 'SC050', TM.TEAM_NM, P.PBANC_SN FROM TB_SBMSN_DCMNT D JOIN TB_BID_PBANC P ON P.PBANC_SN = D.PBANC_SN JOIN TB_TEAM TM ON TM.TEAM_SN = P.SPRVSN_TEAM_SN WHERE P.PBANC_STTS_CD NOT IN ('PS010', 'PS060', 'PS090') AND D.SBMSN_DDLN_DT IS NOT NULL AND (P.BID_DDLN_DT IS NULL OR TRUNC(D.SBMSN_DDLN_DT) <> TRUNC(P.BID_DDLN_DT)) AND D.SBMSN_DDLN_DT >= TO_DATE(#{from}, 'YYYY-MM-DD') AND D.SBMSN_DDLN_DT < TO_DATE(#{to}, 'YYYY-MM-DD') + 1
AND P.SPRVSN_TEAM_SN = #{teamSn}

SELECT FROM TB_SCHDL S JOIN TB_TEAM TM ON TM.TEAM_SN = S.TEAM_SN WHERE S.AUTO_REG_YN = 'N' AND S.SCHDL_BGNG_DT >= TO_DATE(#{from}, 'YYYY-MM-DD') AND S.SCHDL_BGNG_DT < TO_DATE(#{to}, 'YYYY-MM-DD') + 1
AND S.TEAM_SN = #{teamSn}
ORDER BY S.SCHDL_BGNG_DT, S.SCHDL_SN
